import json, base64, requests

with open('/root/.nanobot/providers_models.json') as f:
    cfg = json.load(f)

api_key = cfg['providers']['openrouter']['apiKey']

with open('/root/.nanobot/media/telegram/AgACAgEAAxkBAAEC.jpg', 'rb') as f:
    b64 = base64.b64encode(f.read()).decode()

url = "https://openrouter.ai/api/v1/chat/completions"
headers = {
    "Authorization": f"Bearer {api_key}",
    "Content-Type": "application/json"
}

payload = {
    "model": "google/gemini-2.5-flash",  # good at OCR
    "messages": [
        {
            "role": "user",
            "content": [
                {"type": "text", "text": "请仔细识别这张图片中的所有文字和数学公式，逐字输出。这是一张手写数学笔记/错题本的照片。特别关注极限题目的完整表达式。"},
                {"type": "image_url", "image_url": {"url": f"data:image/jpeg;base64,{b64}"}}
            ]
        }
    ],
    "max_tokens": 2000
}

r = requests.post(url, headers=headers, json=payload, timeout=60)
result = r.json()
print(result.get('choices', [{}])[0].get('message', {}).get('content', 'NO CONTENT'))
if not result.get('choices'):
    print("FULL RESPONSE:", json.dumps(result, indent=2)[:1000])
PYEOF
